import { isNotEmpty, isValidEmail, isValidPhoneBR, } from '../utils/validators.js'; const GOOGLE_SHEETS_URL = 'https://script.google.com/macros/s/AKfycbwqRLNC7lb3CNpsHr-K3001gbhojh_7L5prGfnFkeyKgqxhvwMhICDIF--Xi4YpeaoPHA/exec'; const form = document.querySelector('#partnerForm'); if (form) { const submitBtn = document.getElementById('submitBtn'); const feedback = document.getElementById('formFeedback'); const honeypot = document.getElementById('honeypot'); const setFeedback = (message, type = 'error') => { if (!feedback) return; feedback.textContent = message; feedback.classList.add('visible'); feedback.classList.remove('success', 'error'); feedback.classList.add(type); }; const clearFieldErrors = () => { form.querySelectorAll('input, select, textarea').forEach((field) => { field.classList.remove('is-invalid'); }); }; const markFieldInvalid = (field) => { if (!field) return; field.classList.add('is-invalid'); }; const validateForm = () => { clearFieldErrors(); const fields = { companyName: form.querySelector('#companyName'), ownerName: form.querySelector('#ownerName'), email: form.querySelector('#email'), phone: form.querySelector('#phone'), businessType: form.querySelector('#businessType'), }; const companyName = fields.companyName?.value?.trim() ?? ''; const ownerName = fields.ownerName?.value?.trim() ?? ''; const email = fields.email?.value?.trim() ?? ''; const phone = fields.phone?.value?.trim() ?? ''; const businessType = fields.businessType?.value?.trim() ?? ''; if (!isNotEmpty(companyName)) { markFieldInvalid(fields.companyName); throw new Error('Informe o nome da empresa.'); } if (!isNotEmpty(ownerName)) { markFieldInvalid(fields.ownerName); throw new Error('Informe o nome do responsável.'); } if (!isValidEmail(email)) { markFieldInvalid(fields.email); throw new Error('Informe um e-mail válido.'); } if (!isValidPhoneBR(phone)) { markFieldInvalid(fields.phone); throw new Error('Informe um telefone com DDD válido.'); } if (!isNotEmpty(businessType)) { markFieldInvalid(fields.businessType); throw new Error('Selecione o tipo de negócio.'); } if (honeypot && honeypot.value.trim()) { throw new Error('Solicitação inválida.'); } return { companyName, ownerName, email, phone, businessType, message: form.querySelector('#message')?.value?.trim() ?? '', source: 'landing-page-ecoentregas', }; }; const setLoadingState = (isLoading) => { if (!submitBtn) return; submitBtn.disabled = isLoading; submitBtn.setAttribute('aria-busy', String(isLoading)); submitBtn.textContent = isLoading ? 'Enviando...' : 'Enviar Solicitação'; }; form.addEventListener('submit', async (event) => { event.preventDefault(); try { const payload = validateForm(); if (!GOOGLE_SHEETS_URL) { setFeedback('Configuração do endpoint do Google Apps Script ausente.', 'error'); return; } setLoadingState(true); setFeedback('', 'success'); await fetch(GOOGLE_SHEETS_URL, { method: 'POST', mode: 'no-cors', cache: 'no-store', headers: { 'Content-Type': 'text/plain;charset=utf-8' }, body: JSON.stringify(payload) }); form.reset(); clearFieldErrors(); setFeedback('Sua solicitação foi enviada com sucesso! Nossa equipe entrará em contato em breve.', 'success'); } catch (error) { setFeedback(error.message || 'Não foi possível enviar sua mensagem. Tente novamente.', 'error'); } finally { setLoadingState(false); } }); }